export interface PlayerRecord {
  n: string;
  s: string;
  na: string;
  nc: string;
  c: string;
  l: string;
  p: string;
  sn: number;
  dob: string;
  h: number;
  f: string;
  mv: number;
  g: number;
  a: number;
  t: string[];
  cp: string[];
  active?: boolean;
  legend?: boolean;
}

let _id = 0;
export function nextId(): string {
  _id++;
  return `p-${String(_id).padStart(5, "0")}`;
}

export function normalizeName(s: string): string {
  return s
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[-\u2019']/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

export function searchPlayers(query: string, limit = 8): PlayerRecord[] {
  if (!query || query.trim().length < 1) return [];
  const q = normalizeName(query);
  return PLAYERS.filter(
    (p) =>
      normalizeName(p.n).includes(q) ||
      normalizeName(p.s).includes(q) ||
      normalizeName(p.c).includes(q) ||
      normalizeName(p.na).includes(q) ||
      (p.t && p.t.some((team) => normalizeName(team).includes(q)))
  ).slice(0, limit);
}

export function getPlayerByName(name: string): PlayerRecord | undefined {
  const q = normalizeName(name);
  return PLAYERS.find(
    (p) => normalizeName(p.n) === q || normalizeName(p.s) === q
  );
}

export function getAllPlayers(): PlayerRecord[] {
  return PLAYERS;
}

