let _searchCache: Map<string, PlayerRecord[]> = new Map();

export function searchPlayersCached(query: string, limit = 8): PlayerRecord[] {
  const key = query.toLowerCase().trim() + ':' + limit;
  if (_searchCache.has(key)) return _searchCache.get(key)!;
  const result = searchPlayers(query, limit);
  _searchCache.set(key, result);
  if (_searchCache.size > 500) {
    const firstKey = _searchCache.keys().next().value;
    if (firstKey) _searchCache.delete(firstKey);
  }
  return result;
}
